const countdownSelector = '[data-brunito-countdown]';

function getRemainingLabel(milliseconds) {
  const totalHours = Math.max(0, Math.floor(milliseconds / 3600000));
  const days = Math.floor(totalHours / 24);
  const hours = totalHours % 24;

  if (days > 0) return `${days} d ${hours} h`;

  const minutes = Math.max(0, Math.floor((milliseconds % 3600000) / 60000));
  if (totalHours > 0) return `${totalHours} h ${minutes} min`;

  return `${minutes} min`;
}

function updateCountdown(countdown) {
  const endAt = countdown.dataset.brunitoCountdownEnd || window.BrunitoPromotionEndsAt;
  const endTime = Date.parse(endAt || '');
  const value = countdown.querySelector('[data-brunito-countdown-value]');

  if (!value || Number.isNaN(endTime)) return;

  const remaining = endTime - Date.now();
  if (remaining <= 0) {
    countdown.dataset.countdownExpired = 'true';
    value.textContent = 'Oferta finalizada';
    return;
  }

  countdown.removeAttribute('data-countdown-expired');
  value.textContent = getRemainingLabel(remaining);
}

function initializeCountdowns() {
  const countdowns = [...document.querySelectorAll(countdownSelector)].filter(
    (countdown) => !countdown.dataset.brunitoCountdownReady
  );

  if (!countdowns.length) return;

  countdowns.forEach((countdown) => {
    countdown.dataset.brunitoCountdownReady = 'true';
    updateCountdown(countdown);
  });

  // Keep the label in sync with the real end timestamp, including when the
  // final minute rolls over while the page stays open.
  window.setInterval(() => countdowns.forEach(updateCountdown), 1000);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeCountdowns, { once: true });
} else {
  initializeCountdowns();
}

document.addEventListener('shopify:section:load', initializeCountdowns);
